  connectedCallback() {
    this.render();
    let trustbarButton = this.shadowRoot.querySelectorAll(".nys-trustbar__button");
    for (let button of trustbarButton) {
      button.addEventListener("click", e => {
        this.preventMultiEvents(e);
        this.trustbarChange(button);
      });
      button.addEventListener("touchend", e => {
        this.preventMultiEvents(e);
        this.trustbarChange(button);
      });
    }
    let trustbarMobileCloseX = this.shadowRoot.querySelector(this.classes.trustbarMobileCloseX);
    trustbarMobileCloseX.addEventListener("click", e => {
      this.preventMultiEvents(e);
      this.trustbarChange(trustbarMobileCloseX);
    });
    trustbarMobileCloseX.addEventListener("touchend", e => {
      this.preventMultiEvents(e);
      this.trustbarChange(trustbarMobileCloseX);
    });
    let trustbarInlineCloseX = this.shadowRoot.querySelector(this.classes.trustbarInlineCloseX);
    trustbarInlineCloseX.addEventListener("click", e => {
      this.preventMultiEvents(e);
      this.trustbarChange(trustbarInlineCloseX);
    });
    trustbarInlineCloseX.addEventListener("touchend", e => {
      this.preventMultiEvents(e);
      this.trustbarChange(trustbarInlineCloseX);
    });
    let trustbarMobile = this.shadowRoot.querySelector(this.classes.trustbarMobile);
    trustbarMobile.addEventListener("focus", e => {
      this.wideSearchInActive();
    });
    let trustbarInline = this.shadowRoot.querySelector(this.classes.trustbarInline);
    trustbarInline.addEventListener("focus", e => {
      this.wideSearchInActive();
    });
  }
  adjustUNavAssets(targetExceptions) {
    let mobileTB = [this.shadowRoot.querySelector(this.classes.trustbarMobile), this.shadowRoot.querySelector(this.classes.trustbarMobileButtons), this.shadowRoot.querySelector(this.classes.trustbarMobileContent), this.shadowRoot.querySelector(this.classes.trustbarMobileCloseX)];
    let inlineTB = [this.shadowRoot.querySelector(this.classes.trustbarContent), this.shadowRoot.querySelector(this.classes.trustbarButtons), this.shadowRoot.querySelector(this.classes.trustbarInline), this.shadowRoot.querySelector(this.classes.trustbarInlineCloseX)];
    var menuList = ['mobileTB', 'inlineTB'];
    for (let i = 0; i < menuList.length; i++) {
      if (menuList[i] !== targetExceptions) {
        switch (menuList[i]) {
          case 'mobileTB':
            for (let x = 0; x < mobileTB.length; x++) {
              mobileTB[x].classList.remove('el-is-active');
              this.shadowRoot.querySelector(this.classes.trustbarMobileButtons).setAttribute('aria-expanded', 'false');
            }
            break;
          case 'inlineTB':
            for (let x = 0; x < inlineTB.length; x++) {
              inlineTB[x].classList.remove('el-is-active');
              this.shadowRoot.querySelector(this.classes.trustbarButtons).setAttribute('aria-expanded', 'false');
            }
            break;
        }
      }
    }
  }
  preventMultiEvents(x) {
    x.stopPropagation();
    x.preventDefault();
  }
  trustbarChange(button) {
    let trustbarButtonMobile = this.shadowRoot.querySelector(this.classes.trustbarMobileButtons);
    let trustbarButtonMobileX = this.shadowRoot.querySelector(this.classes.trustbarMobileCloseX);
    let trustbarButtonInline = this.shadowRoot.querySelector(this.classes.trustbarButtons);
    let trustbarButtonInlineX = this.shadowRoot.querySelector(this.classes.trustbarInlineCloseX);
    if (button.classList.contains("el-is-active")) {
      this.adjustUNavAssets();
      trustbarButtonMobile.setAttribute("aria-expanded", "false");
      trustbarButtonInline.setAttribute("aria-expanded", "false");
      trustbarButtonMobileX.setAttribute("aria-expanded", "false");
      trustbarButtonInlineX.setAttribute("aria-expanded", "false");
    } else {
      this.adjustUNavAssets();
      let trustbarContentMobile = this.shadowRoot.querySelector(this.classes.trustbarMobileContent);
      let trustbarMobile = this.shadowRoot.querySelector(this.classes.trustbarMobile);
      trustbarContentMobile.classList.add("el-is-active");
      trustbarMobile.classList.add("el-is-active");
      trustbarButtonMobile.classList.add("el-is-active");
      trustbarButtonMobileX.classList.add("el-is-active");
      let trustbarContentInline = this.shadowRoot.querySelector(this.classes.trustbarContent);
      let trustbarInline = this.shadowRoot.querySelector(this.classes.trustbarInline);
      trustbarContentInline.classList.add("el-is-active");
      trustbarInline.classList.add("el-is-active");
      trustbarButtonInline.classList.add("el-is-active");
      trustbarButtonInlineX.classList.add("el-is-active");
      trustbarButtonMobile.setAttribute("aria-expanded", "true");
      trustbarButtonInline.setAttribute("aria-expanded", "true");
      trustbarButtonMobileX.setAttribute("aria-expanded", "true");
      trustbarButtonInlineX.setAttribute("aria-expanded", "true");
    }
  }
  render() {
    this.shadowRoot.innerHTML = `${this.style}${this.template}`;
  }
