      oCuiTab.dInnerTabWrapper = document.createElement('div');
      oCuiTab.dInnerTabWrapper.setAttribute('id', `tab-${i}`);
      oCuiTab.dInnerTabWrapper.setAttribute('index', `${i}`);
      oCuiTab.dInnerTabWrapper.setAttribute('class', 'innerTabWrapper');
      oCuiTab.dInnerTabWrapper.setAttribute('part', 'innerTabWrapper');
      oCuiTab.dTabList.appendChild(oCuiTab.dInnerTabWrapper);
