class DYNAMIC_BLOCK extends HTMLElement {
  constructor() {
    super();
    this.bShowing = false;
    this.adTriggerElement = null;
    this.bDynamicBlockIsShown = false;
    this.attachShadow({
      mode: "open"
    });
  }
  connectedCallback() {
    this.sTriggerLabel = this.getAttribute('visibleTriggerLabel') ? this.getAttribute('visibleTriggerLabel') : "";
    this.sTriggerValue = this.getAttribute('visibleTriggerValue') ? this.getAttribute('visibleTriggerValue') : "";
    this.shadowRoot.innerHTML = `<div id="content-container" part="content-container"><div style="display: none;" class="hiddenLabelValue" part="hiddenLabelValue">${this.sTriggerLabel}: ${this.sTriggerValue}</div><slot></slot></div>`;
    this.sdContentContainer = this.shadowRoot.querySelector('#content-container');
    this.sdContentContainer.style.display = "none";
    this.sTriggerGroup = this.getAttribute('triggerGroup');
    this.setTriggerElementSelector = this.getAttribute('triggerElem');
    this.bInverse = false;
    this.sTriggerElementValue = null;
    if (this.hasAttribute('triggervalue') && this.hasAttribute('inversetriggervalue')) {
      console.error("CUI-DYNAMIC-BLOCK - Element may not have both trigger and inverse trigger values");
    } else if (this.hasAttribute('triggervalue')) {
      this.sTriggerElementValue = this.getAttribute('triggervalue');
    } else if (this.hasAttribute('inversetriggervalue')) {
      this.sTriggerElementValue = this.getAttribute('inversetriggervalue') ? this.getAttribute('inversetriggervalue') : " ";
      this.bInverse = true;
    }
    this.setAttribute("role", "region");
    this.setAttribute("aria-live", "polite");
    if (this.sTriggerElementValue && this.sTriggerElementValue.length) {
      if (this.sTriggerGroup) {
        this.setTriggerGroup();
      } else {
        this.setTriggerElement();
      }
      this.setupListeners();
      this.triggerChanged();
    } else {
      console.error("CUI-DYNAMIC-BLOCK - Trigger value or state not set");
    }
  }
  show() {
    if (!this.bShowing) {
      this.sdContentContainer.style.display = null;
      this.bShowing = true;
    }
  }
  hide() {
    if (this.bShowing) {
      this.sdContentContainer.style.display = "none";
      this.bShowing = false;
    }
  }
  triggerChanged() {
    if (this.sTriggerGroup) {
      let showBlock = false;
      let aValues = this.sTriggerElementValue.split(',').map(item => item.trim());
      for (let i = 0; i < this.adTriggerElems.length; i++) {
        let dElem = this.adTriggerElems[i];
        if (dElem.checked) {
          if (!this.bInverse && aValues.includes(dElem.value) || this.bInverse && !aValues.includes(dElem.value)) {
            showBlock = true;
          }
        }
      }
      if (showBlock) {
        this.show();
      } else {
        this.hide();
      }
    } else {
      if (this.adTriggerElems && this.adTriggerElems.length === 1) {
        if (this.sTriggerElementValue === ":checked" || this.sTriggerElementValue === ":unchecked") {
          if (this.adTriggerElems[0].checked) {
            if (!this.bInverse && this.sTriggerElementValue === ":checked" || this.bInverse && this.sTriggerElementValue === ":unchecked") {
              this.show();
            } else {
              this.hide();
            }
          } else {
            if (!this.bInverse && this.sTriggerElementValue === ":unchecked" || this.bInverse && this.sTriggerElementValue === ":checked") {
              this.show();
            } else {
              this.hide();
            }
          }
        } else {
          let showBlock = false;
          if (this.sTriggerElementValue.indexOf(',') == -1) {
            if (this.adTriggerElems[0].value.indexOf(',') > -1) {
              let asTriggerElems = this.adTriggerElems[0].value.split(',');
              if (!this.bInverse && asTriggerElems.includes(this.sTriggerElementValue)) {
                showBlock = true;
              }
              if (this.bInverse && asTriggerElems.length > 0) {
                for (let sTriggerElem of asTriggerElems) {
                  if (sTriggerElem !== this.sTriggerElementValue) {
                    showBlock = true;
                  }
                }
              }
            } else {
              if (!this.bInverse && this.sTriggerElementValue === this.adTriggerElems[0].value) {
                showBlock = true;
              }
              if (this.bInverse && this.sTriggerElementValue !== this.adTriggerElems[0].value && this.adTriggerElems[0].value.length > 0) {
                showBlock = true;
              }
            }
          } else {
            let aValues = this.sTriggerElementValue.split(',').map(item => item.trim());
            if (this.adTriggerElems[0].value.indexOf(',') > -1) {
              let asTriggerValues = this.adTriggerElems[0].value.split(',');
              for (let sTriggerValue of asTriggerValues) {
                if (!this.bInverse && aValues.includes(sTriggerValue)) {
                  showBlock = true;
                }
                if (this.bInverse && !aValues.includes(sTriggerValue)) {
                  showBlock = true;
                }
              }
            } else {
              if (!this.bInverse && aValues.includes(this.adTriggerElems[0].value)) {
                showBlock = true;
              }
              if (this.bInverse && !aValues.includes(this.adTriggerElems[0].value) && this.adTriggerElems[0].value.length > 0) {
                showBlock = true;
              }
            }
          }
          if (showBlock) {
            this.show();
          } else {
            this.hide();
          }
        }
      } else {
        console.info("Multi trigger support is coming!");
      }
    }
  }
  triggerReset() {
    this.triggerChanged();
  }
  setTriggerGroup() {
    if (this.sTriggerGroup && this.sTriggerGroup.length) {
      let adTriggerElems = document.querySelectorAll(`[name="${this.sTriggerGroup}"]`);
      if (adTriggerElems.length > 0) {
        this.adTriggerElems = adTriggerElems;
        this.dTriggerGroup = this.adTriggerElems[0].closest('[componentKey]');
      }
    } else {
      console.error("CUI-DYNAMIC-BLOCK - Invalid dynamic block selector");
    }
  }
  setTriggerElement() {
    if (this.setTriggerElementSelector && this.setTriggerElementSelector.length) {
      let asTriggerSelectors = this.setTriggerElementSelector.split(',');
      let adTriggerElems = [];
      let bContinue = true;
      for (let sSelector of asTriggerSelectors) {
        let dTriggerElem = document.querySelector(`${sSelector}`);
        if (!dTriggerElem) {
          dTriggerElem = document.querySelector(`#${sSelector}`);
        }
        if (dTriggerElem) {
          adTriggerElems.push(dTriggerElem);
        } else {
          console.error(`CUI-DYNAMIC-BLOCK - Unable to find a valid trigger element with selector: ${sSelector}`);
          asTriggerSelectors = null;
          bContinue = false;
          break;
        }
      }
      if (bContinue) {
        this.adTriggerElems = adTriggerElems;
      }
    } else {
      console.error("CUI-DYNAMIC-BLOCK - Invalid dynamic block selector");
    }
  }
  setupListeners(bReset = false) {
    if (this.adTriggerElems && this.adTriggerElems.length) {
      for (let dTriggerElem of this.adTriggerElems) {
        dTriggerElem.addEventListener('change', this.triggerChanged.bind(this));
      }
    }
    if (this.dTriggerGroup && !bReset) {
      this.dTriggerGroup.addEventListener('reset', this.reset.bind(this));
    }
  }
  reset() {
    if (this.adTriggerElems && this.adTriggerElems.length) {
      for (let dTriggerElem of this.adTriggerElems) {
        dTriggerElem.removeEventListener('change', this.triggerChanged.bind(this));
      }
    }
    if (this.sTriggerElementValue && this.sTriggerElementValue.length) {
      if (this.sTriggerGroup) {
        this.setTriggerGroup();
      } else {
        this.setTriggerElement();
      }
      this.setupListeners(true);
      this.triggerChanged();
    }
  }
}
